LONDON = 12965000

ps.apply()
fig, (ax1, ax2) = ps.figure(nrows=2, height_px=560)
x = [r[0] - LONDON for r in ROWS]
used = [r[1] / 1e6 for r in ROWS]
target = [(r[2] / 2 if r[0] >= LONDON else r[2]) / 1e6 for r in ROWS]
c0, ls0, m0 = ps.style(0)
c1, ls1, _ = ps.style(1)
ax1.bar(x, used, color=ps.color("sky"), width=0.8, label="gas used")
ax1.step(x, target, where="mid", color=c1, linestyle="--", label="target (half the limit since London)")
ax1.axvline(-0.5, color="0.5", linewidth=0.8)
ax1.text(-0.3, 32, "London, block 12,965,000", fontsize=9, color="0.3")
ax1.set_ylabel("Gas per block (M)")
ax1.set_ylim(0, 42)
ax1.legend(loc="upper right", ncol=2, fontsize=9, frameon=False)

fee = [r[3] / 1e9 for r in ROWS if r[0] >= LONDON]
xf = [r[0] - LONDON for r in ROWS if r[0] >= LONDON]
ax2.plot(xf, fee, color=c0, linestyle=ls0, marker=m0, markersize=3)
ax2.set_ylabel("Base fee (gwei)")
ax2.set_xlabel("Blocks after the London activation block")
ax2.set_xlim(ax1.get_xlim())
imax = max(range(len(fee)), key=lambda i: fee[i])
ax2.annotate(f"{fee[imax]:.1f} gwei after {xf[imax]} blocks", (xf[imax], fee[imax]),
             xytext=(xf[imax] - 14, 12), fontsize=9,
             arrowprops=dict(arrowstyle="-", color="0.4", lw=0.8))
ax2.annotate("starts at 1 gwei, +12.5 % per full block", (0, fee[0]), xytext=(-5, 16), fontsize=9,
             arrowprops=dict(arrowstyle="-", color="0.4", lw=0.8))
ps.caption(fig, "Ethereum mainnet blocks 12,964,995 to 12,965,060, read with eth_getBlockByNumber on 2026-10-23.")
ps.save(fig, __file__)
